import {renderChat,renderPosts,renderLetter,componentCSS} from './components.mjs';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const uid=()=>globalThis.crypto.randomUUID();
export const themes={paper:['素笺','#fffdf6','#383d34'],jade:['青竹','#edf1e4','#3c5140'],ink:['墨屏','#ffffff','#111111'],parchment:['羊皮纸','#f0e4c7','#594c34'],rose:['花笺','#f7ebeb','#614e55'],ocean:['海盐','#e9f0f1','#34535b'],night:['夜读','#222e2b','#d3d8c8'],terminal:['终端','#182321','#a9d6ae']};
export const coverColors=['#425b48','#ac9f80','#3c5560','#75554c','#657657','#4a444b','#8b775b','#8b9990','#3b544e','#9a755c','#667b83','#6f6751'];
export const defaultStyle=()=>({theme:'paper',font:'serif',size:17,line:1.95,indent:true,vertical:false,dropcap:false,decor:'◇ ─── ◇',headingColor:'#476247',titleStyle:'center',componentSkin:'soft',kindle:false});
export const countWords=s=>Array.from(String(s).replace(/\s/g,'')).length;
export function decodeText(bytes,encoding='auto'){
 if(encoding!=='auto')return {text:new TextDecoder(encoding).decode(bytes),encoding};
 if(bytes[0]===255&&bytes[1]===254)return {text:new TextDecoder('utf-16le').decode(bytes),encoding:'utf-16le'};
 if(bytes[0]===254&&bytes[1]===255)return {text:new TextDecoder('utf-16be').decode(bytes),encoding:'utf-16be'};
 try{return {text:new TextDecoder('utf-8',{fatal:true}).decode(bytes),encoding:'utf-8'}}catch{}
 const candidates=['gb18030','big5'].map(enc=>{const text=new TextDecoder(enc).decode(bytes);const score=(text.match(/�/g)||[]).length*20+(text.match(/[\uE000-\uF8FF]/g)||[]).length*5;return {text,encoding:enc,score}});
 candidates.sort((a,b)=>a.score-b.score);return candidates[0];
}
export function splitChapters(text,custom=''){
 const cn='零〇○一二三四五六七八九十百千万两0-9';
 let rule=custom?new RegExp(custom,'i'):new RegExp(`^(?:第[${cn}]+[卷章节回部篇](?:[\\s　:：.、-].*|[^${cn}].*)?|(?:chapter|volume|part)\\s+[0-9ivxlcdm]+(?:\\b.*)|(?:序章|序言|前言|楔子|引子|后记|尾声|终章|番外)(?:[\\s　:：.、0-9一二三四五六七八九十].*)?)$`,'i');
 const lines=text.replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n').split('\n');const out=[];let title='前言',buf=[],type='chapter';
 const flush=()=>{if(buf.join('\n').trim()||out.length)out.push({id:uid(),title,type,text:buf.join('\n').trim(),image:null})};
 for(const raw of lines){const line=raw.trim();if(line.length<=120&&rule.test(line)){flush();title=line;type=/^第[^\s]{1,18}[卷部篇]/.test(line)||/^(volume|part)\s/i.test(line)?'volume':/^第[^\s]{1,18}节/.test(line)?'section':'chapter';buf=[]}else buf.push(raw)}flush();
 if(!out.length)out.push({id:uid(),title:'正文',type:'chapter',text:text.trim(),image:null});return out;
}
export const newBook=(title,text='')=>({id:uid(),title,author:'佚名',description:'',language:'zh-CN',publisher:'',signature:'',cover:null,coverColor:coverColors[0],coverVariant:0,status:'want',tags:'',folder:'',rating:0,created:Date.now(),updated:Date.now(),chapters:splitChapters(text),style:defaultStyle(),fonts:[],progress:{chapter:0,ratio:0},notes:[],stats:{seconds:0,days:{}},source:'txt',encoding:'utf-8'});
export function blocksToHTML(text){
 const lines=text.split('\n');let out='',block=null,buf=[];
 const close=()=>{if(!block)return;const body=buf.map(esc).join('<br/>');const customTitle=block.customTitle||'';if(block.kind==='chat')out+=renderChat(buf,block.title);else if(block.kind==='forum')out+=renderPosts(buf,customTitle);else if(block.kind==='letter')out+=renderLetter(buf,customTitle);else out+=`<div class="component ${esc(block.kind)}">${customTitle?`<strong>${esc(customTitle)}</strong>`:''}${body}</div>`;block=null;buf=[]};
 for(const line of lines){const m=line.match(/^\[\[(chat|forum|social|system|author|quote|list|letter)(?:\|([^\]]*))?\]\]$/);if(m){close();block={kind:m[1],customTitle:m[2]?.trim()||'',title:m[2]||({chat:'对话',forum:'帖子',social:'动态',system:'系统公告',author:'作者有话说',quote:'引用',list:'列表',letter:'信件'}[m[1]])};continue}if(/^\[\[\/\]\]$/.test(line)){close();continue}if(block)buf.push(line);else if(line.trim())out+=`<p>${esc(line)}</p>`}close();return out;
}
export function bookCSS(style,fonts=[]){const t=themes[style.theme]||themes.paper;const family=style.font==='sans'?'sans-serif':style.font==='serif'?'serif':`"${style.font}"`;return `${fonts.map((f,i)=>`@font-face{font-family:"${f.name.replace(/["\\]/g,'')}";src:url('../Fonts/font${i}.${f.ext}')}`).join('\n')}
body{background:${style.kindle?'#fff':t[1]};color:${style.kindle?'#111':t[2]};font-family:${family};font-size:${style.size}px;line-height:${style.line};padding:1em;${style.vertical?'writing-mode:vertical-rl;':''}}h1{text-align:${style.titleStyle||'center'};color:${style.kindle?'#111':style.headingColor};font-size:1.55em;margin:2em 0}p{text-indent:${style.indent?'2em':'0'};margin:.2em 0 .8em;orphans:2;widows:2;${style.dropcap?'':''}}${style.dropcap?'p:first-of-type:first-letter{font-size:2.3em;float:left;line-height:1;padding:.1em}':''}img{max-width:100%;height:auto;display:block;margin:1em auto}.chapter-image{max-height:18em}.title-decor{text-align:center;opacity:.55;letter-spacing:.3em;margin:2em 0}.component{border:1px solid #aaa;padding:1em;margin:1em 0;break-inside:auto;border-radius:${style.componentSkin==='square'||style.kindle?'0':'8px'};${style.componentSkin==='parchment'?'background:#eee2c5;color:#453b2c;':''}}.component strong{display:block;font-size:.8em;margin-bottom:.6em}.quote{border:0;border-left:3px solid #888;font-style:italic}.system{text-align:center;border-style:dashed}.forum{border-radius:0}.bubble{background:${style.kindle?'#eee':'#e1ebdf'};color:#263d2d;border:1px solid #aaa;padding:.8em;margin:1em 15% 1em 0;border-radius:10px}.bubble.right{margin:1em 0 1em 15%;background:${style.kindle?'#ddd':'#cbdcc9'}}.volume-page{padding-top:25vh;text-align:center}.cover{padding:0;margin:0;text-align:center}.cover img{width:100%;max-height:95vh;object-fit:contain}.cover-art{padding:25vh 1em;background:${style.coverColor||'#425b48'};color:#fff;height:40vh}.cover-art h1{color:#fff}.book-signature{font-size:.8em;text-align:center;margin-top:3em}${componentCSS(style.kindle)}`;
}
export const xmlHeader='<?xml version="1.0" encoding="utf-8"?>';
export function dataBytes(data){const m=data.match(/^data:([^;,]+)?(;base64)?,(.*)$/s);if(!m)throw Error('无效的本地资源');const str=m[2]?atob(m[3]):decodeURIComponent(m[3]);return {mime:m[1]||'application/octet-stream',bytes:Uint8Array.from(str,c=>c.charCodeAt(0))}}
export function makeEpub(book,zip){
 if(!book.chapters.length)throw Error('书籍至少需要一章');const files={},enc=s=>new TextEncoder().encode(s),manifest=[],spine=[];const add=(path,data,type,id,props='')=>{files['OEBPS/'+path]=typeof data==='string'?enc(data):data;manifest.push(`<item id="${id}" href="${esc(path)}" media-type="${type}"${props?` properties="${props}"`:''}/>`)};
 files.mimetype=[enc('application/epub+zip'),{level:0}];files['META-INF/container.xml']=enc(`${xmlHeader}<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container"><rootfiles><rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/></rootfiles></container>`);
 const wrap=(title,body)=>`${xmlHeader}<html xmlns="http://www.w3.org/1999/xhtml" xml:lang="${esc(book.language||'zh-CN')}"><head><title>${esc(title)}</title><link rel="stylesheet" type="text/css" href="../Styles/book.css"/></head><body>${body}</body></html>`;
 add('Styles/book.css',bookCSS({...book.style,coverColor:book.coverColor},book.fonts),'text/css','style');
 let coverBody=`<div class="cover-art"><h1>${esc(book.title)}</h1><p>${esc(book.author)}</p></div>`;
 if(book.cover){const d=dataBytes(book.cover);const ext=d.mime.includes('png')?'png':d.mime.includes('svg')?'svg':'jpg';add('Images/cover.'+ext,d.bytes,d.mime,'cover-image','cover-image');coverBody=`<div class="cover"><img src="../Images/cover.${ext}" alt="${esc(book.title)}"/></div>`}
 add('Text/cover.xhtml',wrap(book.title,coverBody),'application/xhtml+xml','cover');spine.push('<itemref idref="cover"/>');
 for(const [i,f]of book.fonts.entries()){const d=dataBytes(f.data);add(`Fonts/font${i}.${f.ext}`,d.bytes,f.ext==='otf'?'font/otf':f.ext==='woff2'?'font/woff2':f.ext==='woff'?'font/woff':'font/ttf','font'+i)}
 const navEntries=[];
 book.chapters.forEach((ch,i)=>{let img='';if(ch.image){const d=dataBytes(ch.image);const ext=d.mime.includes('png')?'png':'jpg';const path=`Images/ch${i}.${ext}`;add(path,d.bytes,d.mime,'img'+i);img=`<img class="chapter-image" src="../${path}" alt="章节插图"/>`}
 let body=ch.originalHtml||blocksToHTML(ch.text);body=`<section${ch.type==='volume'?' class="volume-page"':''}><h1>${esc(ch.title)}</h1>${img}${book.style.decor?`<div class="title-decor">${esc(book.style.decor)}</div>`:''}${body}${book.signature?`<div class="book-signature">${esc(book.signature)}</div>`:''}</section>`;
 add(`Text/ch${i}.xhtml`,wrap(ch.title,body),'application/xhtml+xml','ch'+i,body.includes('<svg ')?'svg':'');spine.push(`<itemref idref="ch${i}"/>`);navEntries.push({href:`Text/ch${i}.xhtml`,title:ch.title,type:ch.type})});
 const toc=navEntries.map(n=>`<li><a href="${n.href}">${esc(n.title)}</a></li>`).join('');
 add('nav.xhtml',`${xmlHeader}<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops" xml:lang="${esc(book.language||'zh-CN')}"><head><title>目录</title></head><body><nav epub:type="toc" id="toc"><h1>目录</h1><ol>${toc}</ol></nav></body></html>`,'application/xhtml+xml','nav','nav');
 add('toc.ncx',`${xmlHeader}<ncx xmlns="http://www.daisy.org/z3986/2005/ncx/" version="2005-1"><head><meta name="dtb:uid" content="urn:uuid:${book.id}"/></head><docTitle><text>${esc(book.title)}</text></docTitle><navMap>${navEntries.map((n,i)=>`<navPoint id="n${i}" playOrder="${i+1}"><navLabel><text>${esc(n.title)}</text></navLabel><content src="${n.href}"/></navPoint>`).join('')}</navMap></ncx>`,'application/x-dtbncx+xml','ncx');
 files['OEBPS/content.opf']=enc(`${xmlHeader}<package xmlns="http://www.idpf.org/2007/opf" version="3.0" unique-identifier="bookid" xml:lang="${esc(book.language||'zh-CN')}"><metadata xmlns:dc="http://purl.org/dc/elements/1.1/"><dc:identifier id="bookid">urn:uuid:${book.id}</dc:identifier><dc:title>${esc(book.title)}</dc:title><dc:creator>${esc(book.author)}</dc:creator><dc:language>${esc(book.language||'zh-CN')}</dc:language><dc:description>${esc(book.description)}</dc:description><dc:publisher>${esc(book.publisher)}</dc:publisher><meta property="dcterms:modified">${new Date().toISOString().replace(/\.\d+Z$/,'Z')}</meta>${book.cover?'<meta name="cover" content="cover-image"/>':''}</metadata><manifest>${manifest.join('')}</manifest><spine toc="ncx"${book.style.vertical?' page-progression-direction="rtl"':''}>${spine.join('')}</spine></package>`);
 return zip(files,{level:6});
}
export function validateBook(b){if(!b||typeof b.title!=='string'||!Array.isArray(b.chapters)||!b.chapters.length||b.chapters.length>50000)throw Error('项目格式无效');for(const c of b.chapters)if(typeof c.text!=='string'||typeof c.title!=='string')throw Error('章节格式无效');return b}
